<?php
namespace App\Http\Controllers;
use App\Http\Requests\StoreTransportRouteRequest;use App\Models\{TransportPerson,TransportRoute,TransportVehicle};use App\Services\TransportAuditService;
class TransportRouteController extends Controller {public function index(){ $company=auth()->user()->company_id;return view('transport.routes.index',['routes'=>TransportRoute::forCompany($company)->with(['vehicle','driver.employee','monitor.employee','stops'])->latest()->paginate(20),'vehicles'=>TransportVehicle::forCompany($company)->where('status','active')->orderBy('plate')->get(),'drivers'=>TransportPerson::forCompany($company)->with('employee')->where('status','active')->where('is_driver',true)->get(),'monitors'=>TransportPerson::forCompany($company)->with('employee')->where('status','active')->where('is_monitor',true)->get()]);}public function store(StoreTransportRouteRequest $r,TransportAuditService $audit){$route=TransportRoute::create($r->validated()+['company_id'=>$r->user()->company_id,'created_by'=>$r->user()->id]);$audit->record($route->company_id,'transport_route_created','route',$route->id,$r->user()->id);return back()->with('success','Ruta registrada.');}public function update(StoreTransportRouteRequest $r,TransportRoute $transportRoute,TransportAuditService $audit){$this->own($transportRoute);$transportRoute->update($r->validated()+['updated_by'=>$r->user()->id]);$audit->record($transportRoute->company_id,'transport_route_updated','route',$transportRoute->id,$r->user()->id);return back()->with('success','Ruta actualizada.');}public function destroy(TransportRoute $transportRoute,TransportAuditService $audit){$this->own($transportRoute);$transportRoute->update(['status'=>'inactive','updated_by'=>auth()->id()]);$audit->record($transportRoute->company_id,'transport_route_deactivated','route',$transportRoute->id,auth()->id());return back()->with('success','Ruta desactivada sin eliminar su historial.');}private function own($m):void{abort_unless((int)$m->company_id===(int)auth()->user()->company_id,404);}}
